     1→'use client';
     2→
     3→/**
     4→ * Real-Time Simulation Dashboard - Paradigm-Focused Edition
     5→ *
     6→ * Ultra-futuristic dashboard with Multi-Paradigm DUI as centerpiece.
     7→ * Inspired by Elysium (2013) medical/systems interfaces.
     8→ * High-contrast, data-dense, clean geometry, glowing accents.
     9→ *
    10→ * Features:
    11→ * - Multi-Paradigm DUI histogram with sparklines (front & center)
    12→ * - Comprehensive economic indicators panel
    13→ * - Expanded government information with active policies
    14→ * - Real-time sparkline trends throughout
    15→ * - Color-coded severity indicators
    16→ * - Glowing effects for critical states
    17→ * - Web Worker-based non-blocking simulation
    18→ */
    19→
    20→import { useState, useEffect, useCallback, useRef } from 'react';
    21→import { useSimulationWorker } from '@/lib/contexts/SimulationWorkerContext';
    22→import { type StateDelta, type InitialStateSnapshot } from '@/lib/simulationWorkerClient';
    23→import { Sparkline } from '@/components/Sparkline';
    24→import type { ScenarioMode } from '@/types/game';
    25→
    26→// History tracking for sparklines
    27→interface MetricHistory {
    28→  qualityOfLife: number[];
    29→  population: number[];
    30→  aiCapability: number[];
    31→  climateChange: number[];
    32→  socialCohesion: number[];
    33→  extinctionRisk: number[];
    34→  dystopiaRisk: number[];
    35→  utopiaProgress: number[];
    36→  // Paradigm histories
    37→  westernLiberal: number[];
    38→  development: number[];
    39→  ecological: number[];
    40→  indigenous: number[];
    41→  // Economic histories
    42→  gdp: number[];
    43→  employment: number[];
    44→  inequality: number[];
    45→  inflation: number[];
    46→}
    47→
    48→// Panel component for consistent styling
    49→interface PanelProps {
    50→  title: string;
    51→  children: React.ReactNode;
    52→  className?: string;
    53→  glow?: 'cyan' | 'amber' | 'red' | 'green';
    54→}
    55→
    56→const Panel: React.FC<PanelProps> = ({ title, children, className = '', glow }) => {
    57→  const glowColors = {
    58→    cyan: 'shadow-[0_0_20px_rgba(0,240,255,0.3)]',
    59→    amber: 'shadow-[0_0_20px_rgba(255,176,0,0.3)]',
    60→    red: 'shadow-[0_0_20px_rgba(255,0,64,0.3)]',
    61→    green: 'shadow-[0_0_20px_rgba(0,255,136,0.3)]'
    62→  };
    63→
    64→  return (
    65→    <div className={`bg-black/90 border border-white/10 p-4 ${glow ? glowColors[glow] : ''} ${className}`}>
    66→      <h3 className="text-xs font-light uppercase tracking-[0.2em] text-white/40 mb-3">
    67→        {title}
    68→      </h3>
    69→      <div>{children}</div>
    70→    </div>
    71→  );
    72→};
    73→
    74→// Metric display component
    75→interface MetricProps {
    76→  label: string;
    77→  value: string | number;
    78→  unit?: string;
    79→  trend?: 'up' | 'down' | 'stable';
    80→  color?: 'green' | 'yellow' | 'red' | 'cyan' | 'white';
    81→  sparkline?: number[];
    82→  className?: string;
    83→}
    84→
    85→const Metric: React.FC<MetricProps> = ({
    86→  label,
    87→  value,
    88→  unit = '',
    89→  trend,
    90→  color = 'white',
    91→  sparkline,
    92→  className = ''
    93→}) => {
    94→  const colorMap = {
    95→    green: 'text-green-400',
    96→    yellow: 'text-yellow-400',
    97→    red: 'text-red-400',
    98→    cyan: 'text-cyan-400',
    99→    white: 'text-white'
   100→  };
   101→
   102→  const trendIcon = trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→';
   103→
   104→  return (
   105→    <div className={`${className}`}>
   106→      <div className="text-[10px] text-white/30 uppercase tracking-wider mb-1">{label}</div>
   107→      <div className="flex items-baseline gap-2">
   108→        <span className={`text-2xl font-light tabular-nums ${colorMap[color]}`}>
   109→          {value}
   110→        </span>
   111→        {unit && <span className="text-sm text-white/40">{unit}</span>}
   112→        {trend && <span className="text-sm text-white/40">{trendIcon}</span>}
   113→      </div>
   114→      {sparkline && sparkline.length > 1 && (
   115→        <div className="mt-2">
   116→          <Sparkline
   117→            data={sparkline}
   118→            width={120}
   119→            height={25}
   120→            color={color === 'green' ? '#00FF88' :
   121→                   color === 'yellow' ? '#FFB000' :
   122→                   color === 'red' ? '#FF0040' :
   123→                   color === 'cyan' ? '#00F0FF' : '#FFFFFF'}
   124→            showArea
   125→          />
   126→        </div>
   127→      )}
   128→    </div>
   129→  );
   130→};
   131→
   132→// Paradigm Time Series component - shows historical values over time
   133→interface ParadigmTimeSeriesProps {
   134→  name: string;
   135→  value: number;
   136→  color: string;
   137→  history?: number[];
   138→  trend?: 'up' | 'down' | 'stable';
   139→  allHistories?: {
   140→    westernLiberal: number[];
   141→    development: number[];
   142→    ecological: number[];
   143→    indigenous: number[];
   144→  };
   145→}
   146→
   147→const ParadigmTimeSeries: React.FC<ParadigmTimeSeriesProps> = ({ name, value, color, history, trend, allHistories }) => {
   148→  const trendIcon = trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→';
   149→  const percentage = (value * 100).toFixed(1);
   150→
   151→  // Determine status based on value
   152→  const status = value >= 0.7 ? 'OPTIMAL' : value >= 0.4 ? 'STABLE' : value >= 0.2 ? 'WARNING' : 'CRITICAL';
   153→  const statusColor = value >= 0.7 ? 'text-green-400' : value >= 0.4 ? 'text-cyan-400' : value >= 0.2 ? 'text-yellow-400' : 'text-red-400';
   154→
   155→  // Convert history to percentage values for display
   156→  const historyPercentages = (history || []).map(v => v * 100);
   157→
   158→  // Calculate min/max for better visualization
   159→  const minValue = Math.min(...(historyPercentages.length > 0 ? historyPercentages : [0]));
   160→  const maxValue = Math.max(...(historyPercentages.length > 0 ? historyPercentages : [100]));
   161→  const range = maxValue - minValue || 100;
   162→
   163→  return (
   164→    <div className="space-y-4">
   165→      {/* Header with name and current value */}
   166→      <div className="flex items-center justify-between">
   167→        <div className="flex items-center gap-3">
   168→          <span className="text-base font-light text-white/90">{name}</span>
   169→        </div>
   170→        <div className="flex items-center gap-3">
   171→          <span className={`text-xs ${statusColor} font-mono uppercase tracking-wider`}>{status}</span>
   172→          <span className="text-sm text-white/40">{trendIcon}</span>
   173→          <span className="text-2xl font-light text-white tabular-nums">{percentage}%</span>
   174→        </div>
   175→      </div>
   176→
   177→      {/* Time Series Area Chart */}
   178→      <div className="relative bg-black border border-white/20 overflow-hidden" style={{ height: '120px' }}>
   179→        {historyPercentages.length > 1 ? (
   180→          <>
   181→            {/* Chart container with proper sizing */}
   182→            <div className="w-full h-full relative">
   183→              {/* Reference lines at 20%, 40%, 70% thresholds */}
   184→              <div className="absolute inset-0 pointer-events-none px-2">
   185→                {/* 70% threshold - optimal */}
   186→                <div
   187→                  className="absolute w-full border-t border-green-400/20"
   188→                  style={{ top: `${100 - ((70 - minValue) / range * 100)}%` }}
   189→                >
   190→                  <span className="absolute -top-2 right-0 text-[9px] text-green-400/40">70%</span>
   191→                </div>
   192→                {/* 40% threshold - stable */}
   193→                <div
   194→                  className="absolute w-full border-t border-cyan-400/20"
   195→                  style={{ top: `${100 - ((40 - minValue) / range * 100)}%` }}
   196→                >
   197→                  <span className="absolute -top-2 right-0 text-[9px] text-cyan-400/40">40%</span>
   198→                </div>
   199→                {/* 20% threshold - warning */}
   200→                <div
   201→                  className="absolute w-full border-t border-yellow-400/20"
   202→                  style={{ top: `${100 - ((20 - minValue) / range * 100)}%` }}
   203→                >
   204→                  <span className="absolute -top-2 right-0 text-[9px] text-yellow-400/40">20%</span>
   205→                </div>
   206→              </div>
   207→
   208→              {/* Main sparkline with area fill - constrained to container */}
   209→              <div className="absolute inset-0 p-1">
   210→                <Sparkline
   211→                  data={historyPercentages}
   212→                  width={280}
   213→                  height={114}
   214→                  color={color}
   215→                  showArea
   216→                  strokeWidth={2}
   217→                  className="mx-auto"
   218→                />
   219→              </div>
   220→            </div>
   221→
   222→            {/* Time labels */}
   223→            <div className="absolute bottom-0 left-0 right-0 flex justify-between text-[9px] text-white/30">
   224→              <span>-{historyPercentages.length}mo</span>
   225→              <span>-{Math.floor(historyPercentages.length / 2)}mo</span>
   226→              <span>now</span>
   227→            </div>
   228→          </>
   229→        ) : (
   230→          <div className="h-full flex items-center justify-center">
   231→            <div className="text-white/20 text-sm">Collecting historical data...</div>
   232→          </div>
   233→        )}
   234→      </div>
   235→
   236→      {/* Status box with insight */}
   237→      <div className="p-2 rounded bg-white/5 border border-white/10">
   238→        <div className="flex items-center justify-between">
   239→          <div className="text-xs text-white/40">
   240→            {historyPercentages.length > 10 && (
   241→              <>
   242→                {/* Show average over last 10 months */}
   243→                <span>10mo avg: {(historyPercentages.slice(-10).reduce((a, b) => a + b, 0) / 10).toFixed(1)}%</span>
   244→              </>
   245→            )}
   246→          </div>
   247→          <div className="flex items-center gap-2">
   248→            <span className="text-xs text-white/40">Current:</span>
   249→            <span className={`text-sm font-medium ${statusColor}`}>{percentage}%</span>
   250→          </div>
   251→        </div>
   252→      </div>
   253→    </div>
   254→  );
   255→};
   256→
   257→export default function RealtimeDashboard() {
   258→  // Get shared worker from context
   259→  const { client, initialized, running, scenario, month: contextMonth } = useSimulationWorker();
   260→
   261→  // Local state for error handling
   262→  const [error, setError] = useState<string | null>(null);
   263→
   264→  // Core metrics
   265→  const [month, setMonth] = useState(0);
   266→  const [day, setDay] = useState(1);
   267→  const [calendarDate, setCalendarDate] = useState<string | null>(null);
   268→  const [qualityOfLife, setQualityOfLife] = useState<number | null>(null);
   269→  const [population, setPopulation] = useState<number | null>(null);
   270→  const [aiCount, setAiCount] = useState<number | null>(null);
   271→
   272→  // AI System
   273→  const [avgAICapability, setAvgAICapability] = useState<number | null>(null);
   274→  const [alignedAICount, setAlignedAICount] = useState<number | null>(null);
   275→  const [misalignedAICount, setMisalignedAICount] = useState<number | null>(null);
   276→  const [sleeperAgentCount, setSleeperAgentCount] = useState<number | null>(null);
   277→
   278→  // Environmental
   279→  const [climateChange, setClimateChange] = useState<number | null>(null);
   280→  const [resourceDepletion, setResourceDepletion] = useState<number | null>(null);
   281→  const [biodiversityLoss, setBiodiversityLoss] = useState<number | null>(null);
   282→  const [pollutionLevel, setPollutionLevel] = useState<number | null>(null);
   283→  const [planetaryBoundariesCrossed, setPlanetaryBoundariesCrossed] = useState<number | null>(null);
   284→  const [environmentalDebtLevel, setEnvironmentalDebtLevel] = useState<number | null>(null);
   285→
   286→  // Social
   287→  const [socialCohesion, setSocialCohesion] = useState<number | null>(null);
   288→  const [institutionalTrust, setInstitutionalTrust] = useState<number | null>(null);
   289→  const [meaningLevel, setMeaningLevel] = useState<number | null>(null);
   290→  const [socialDebtLevel, setSocialDebtLevel] = useState<number | null>(null);
   291→
   292→  // Crisis
   293→  const [activeCrises, setActiveCrises] = useState<Array<{ type: string; severity: number; duration: number }>>([]);
   294→  const [phosphorusDepletion, setPhosphorusDepletion] = useState<number | null>(null);
   295→  const [freshwaterStress, setFreshwaterStress] = useState<number | null>(null);
   296→  const [oceanAcidification, setOceanAcidification] = useState<number | null>(null);
   297→  const [novelEntitiesLevel, setNovelEntitiesLevel] = useState<number | null>(null);
   298→
   299→  // Government
   300→  const [governmentAIRegulation, setGovernmentAIRegulation] = useState<number | null>(null);
   301→  const [governmentInvestment, setGovernmentInvestment] = useState<number | null>(null);
   302→  const [governmentComprehension, setGovernmentComprehension] = useState<number | null>(null);
   303→  const [internationalCooperation, setInternationalCooperation] = useState<number | null>(null);
   304→  const [activePolicies, setActivePolicies] = useState<string[]>([]);
   305→  const [legislativeActivity, setLegislativeActivity] = useState<number>(0);
   306→  const [publicTrust, setPublicTrust] = useState<number | null>(null);
   307→
   308→  // Technology
   309→  const [deployedTechCount, setDeployedTechCount] = useState<number | null>(null);
   310→  const [techRiskLevel, setTechRiskLevel] = useState<number | null>(null);
   311→
   312→  // Outcomes
   313→  const [dystopiaProgression, setDystopiaProgression] = useState<number | null>(null);
   314→  const [utopiaProgress, setUtopiaProgress] = useState<number | null>(null);
   315→  const [extinctionProbability, setExtinctionProbability] = useState<number | null>(null);
   316→  const [outcomeType, setOutcomeType] = useState<string>('In Progress');
   317→  const [activeSpirals, setActiveSpirals] = useState<Array<{ type: string; strength: number; duration: number }>>([]);
   318→
   319→  // Multi-Paradigm DUI
   320→  const [westernLiberalIndex, setWesternLiberalIndex] = useState<number | null>(null);
   321→  const [developmentIndex, setDevelopmentIndex] = useState<number | null>(null);
   322→  const [ecologicalIndex, setEcologicalIndex] = useState<number | null>(null);
   323→  const [indigenousIndex, setIndigenousIndex] = useState<number | null>(null);
   324→
   325→  // Economic Indicators (simulated for now)
   326→  const [gdp, setGdp] = useState<number>(100);
   327→  const [employment, setEmployment] = useState<number>(0.95);
   328→  const [wealthInequality, setWealthInequality] = useState<number>(0.35);
   329→  const [inflationRate, setInflationRate] = useState<number>(0.02);
   330→
   331→  // Event log
   332→  const [events, setEvents] = useState<Array<{
   333→    month: number;
   334→    message: string;
   335→    type: string;
   336→    category?: string;
   337→  }>>([]);
   338→
   339→  // No local configuration state - managed globally by Navigation via context
   340→
   341→  // Performance tracking
   342→  const [fps, setFps] = useState(0);
   343→  const lastUpdateRef = useRef(Date.now());
   344→  const updateCountRef = useRef(0);
   345→
   346→  // Metric history for sparklines (keep last 50 points)
   347→  const [history, setHistory] = useState<MetricHistory>({
   348→    qualityOfLife: [],
   349→    population: [],
   350→    aiCapability: [],
   351→    climateChange: [],
   352→    socialCohesion: [],
   353→    extinctionRisk: [],
   354→    dystopiaRisk: [],
   355→    utopiaProgress: [],
   356→    westernLiberal: [],
   357→    development: [],
   358→    ecological: [],
   359→    indigenous: [],
   360→    gdp: [],
   361→    employment: [],
   362→    inequality: [],
   363→    inflation: []
   364→  });
   365→
   366→  // Sync month from context
   367→  useEffect(() => {
   368→    setMonth(contextMonth);
   369→  }, [contextMonth]);
   370→
   371→  // Setup worker event listeners for detailed metrics
   372→  useEffect(() => {
   373→    if (!client) {
   374→      console.log('[RealtimeDashboard] No worker client available yet');
   375→      return;
   376→    }
   377→
   378→    const handleInitialized = (snapshot: InitialStateSnapshot, startDate: string) => {
   379→      setMonth(snapshot.currentMonth);
   380→      setDay(1);
   381→      setCalendarDate(startDate);
   382→      setQualityOfLife(snapshot.qualityOfLife);
   383→      setPopulation(snapshot.population);
   384→      setAiCount(snapshot.aiCount);
   385→      setError(null);
   386→      console.log('[RealtimeDashboard] Initialized:', snapshot, 'Start date:', startDate);
   387→    };
   388→
   389→    const handleUpdate = (delta: StateDelta, currentMonth: number, currentDay: number, date: string, timestamp: number) => {
   390→      // Update calendar
   391→      setDay(currentDay);
   392→      setCalendarDate(date);
   393→      // Apply delta to state
   394→      if (delta.currentMonth !== undefined) setMonth(delta.currentMonth);
   395→      if (delta.qualityOfLife !== undefined) {
   396→        setQualityOfLife(delta.qualityOfLife);
   397→        setHistory(h => ({
   398→          ...h,
   399→          qualityOfLife: [...h.qualityOfLife.slice(-49), delta.qualityOfLife!]
   400→        }));
   401→      }
   402→      if (delta.population !== undefined) {
   403→        setPopulation(delta.population);
   404→        setHistory(h => ({
   405→          ...h,
   406→          population: [...h.population.slice(-49), delta.population!]
   407→        }));
   408→      }
   409→
   410→      // AI System
   411→      if (delta.aiCount !== undefined) setAiCount(delta.aiCount);
   412→      if (delta.avgAICapability !== undefined) {
   413→        setAvgAICapability(delta.avgAICapability);
   414→        setHistory(h => ({
   415→          ...h,
   416→          aiCapability: [...h.aiCapability.slice(-49), delta.avgAICapability!]
   417→        }));
   418→      }
   419→      if (delta.alignedAICount !== undefined) setAlignedAICount(delta.alignedAICount);
   420→      if (delta.misalignedAICount !== undefined) setMisalignedAICount(delta.misalignedAICount);
   421→      if (delta.sleeperAgentCount !== undefined) setSleeperAgentCount(delta.sleeperAgentCount);
   422→
   423→      // Environmental
   424→      if (delta.climateChange !== undefined) {
   425→        setClimateChange(delta.climateChange);
   426→        setHistory(h => ({
   427→          ...h,
   428→          climateChange: [...h.climateChange.slice(-49), delta.climateChange!]
   429→        }));
   430→      }
   431→      if (delta.resourceDepletion !== undefined) setResourceDepletion(delta.resourceDepletion);
   432→      if (delta.biodiversityLoss !== undefined) setBiodiversityLoss(delta.biodiversityLoss);
   433→      if (delta.pollutionLevel !== undefined) setPollutionLevel(delta.pollutionLevel);
   434→      if (delta.planetaryBoundariesCrossed !== undefined) setPlanetaryBoundariesCrossed(delta.planetaryBoundariesCrossed);
   435→      if (delta.environmentalDebtLevel !== undefined) setEnvironmentalDebtLevel(delta.environmentalDebtLevel);
   436→
   437→      // Social
   438→      if (delta.socialCohesion !== undefined) {
   439→        setSocialCohesion(delta.socialCohesion);
   440→        setHistory(h => ({
   441→          ...h,
   442→          socialCohesion: [...h.socialCohesion.slice(-49), delta.socialCohesion!]
   443→        }));
   444→      }
   445→      if (delta.institutionalTrust !== undefined) {
   446→        setInstitutionalTrust(delta.institutionalTrust);
   447→        setPublicTrust(delta.institutionalTrust); // Mirror as public trust for now
   448→      }
   449→      if (delta.meaningLevel !== undefined) setMeaningLevel(delta.meaningLevel);
   450→      if (delta.socialDebtLevel !== undefined) setSocialDebtLevel(delta.socialDebtLevel);
   451→
   452→      // Crisis
   453→      if (delta.activeCrises !== undefined) setActiveCrises(delta.activeCrises);
   454→      if (delta.phosphorusDepletion !== undefined) setPhosphorusDepletion(delta.phosphorusDepletion);
   455→      if (delta.freshwaterStress !== undefined) setFreshwaterStress(delta.freshwaterStress);
   456→      if (delta.oceanAcidification !== undefined) setOceanAcidification(delta.oceanAcidification);
   457→      if (delta.novelEntitiesLevel !== undefined) setNovelEntitiesLevel(delta.novelEntitiesLevel);
   458→
   459→      // Government
   460→      if (delta.governmentAIRegulation !== undefined) setGovernmentAIRegulation(delta.governmentAIRegulation);
   461→      if (delta.governmentInvestment !== undefined) setGovernmentInvestment(delta.governmentInvestment);
   462→      if (delta.governmentComprehension !== undefined) setGovernmentComprehension(delta.governmentComprehension);
   463→      if (delta.internationalCooperation !== undefined) setInternationalCooperation(delta.internationalCooperation);
   464→
   465→      // Technology
   466→      if (delta.deployedTechCount !== undefined) setDeployedTechCount(delta.deployedTechCount);
   467→      if (delta.techRiskLevel !== undefined) setTechRiskLevel(delta.techRiskLevel);
   468→
   469→      // Outcomes
   470→      if (delta.dystopiaProgression !== undefined) {
   471→        setDystopiaProgression(delta.dystopiaProgression);
   472→        setHistory(h => ({
   473→          ...h,
   474→          dystopiaRisk: [...h.dystopiaRisk.slice(-49), delta.dystopiaProgression!]
   475→        }));
   476→      }
   477→      if (delta.utopiaProgress !== undefined) {
   478→        setUtopiaProgress(delta.utopiaProgress);
   479→        setHistory(h => ({
   480→          ...h,
   481→          utopiaProgress: [...h.utopiaProgress.slice(-49), delta.utopiaProgress!]
   482→        }));
   483→      }
   484→      if (delta.extinctionProbability !== undefined) {
   485→        setExtinctionProbability(delta.extinctionProbability);
   486→        setHistory(h => ({
   487→          ...h,
   488→          extinctionRisk: [...h.extinctionRisk.slice(-49), delta.extinctionProbability!]
   489→        }));
   490→      }
   491→      if (delta.outcomeType !== undefined) setOutcomeType(delta.outcomeType);
   492→      if (delta.activeSpirals !== undefined) setActiveSpirals(delta.activeSpirals);
   493→
   494→      // Multi-Paradigm DUI
   495→      if (delta.westernLiberalIndex !== undefined) {
   496→        setWesternLiberalIndex(delta.westernLiberalIndex);
   497→        setHistory(h => ({
   498→          ...h,
   499→          westernLiberal: [...h.westernLiberal.slice(-49), delta.westernLiberalIndex!]
   500→        }));
   501→      }
   502→      if (delta.developmentIndex !== undefined) {
   503→        setDevelopmentIndex(delta.developmentIndex);
   504→        setHistory(h => ({
   505→          ...h,
   506→          development: [...h.development.slice(-49), delta.developmentIndex!]
   507→        }));
   508→      }
   509→      if (delta.ecologicalIndex !== undefined) {
   510→        setEcologicalIndex(delta.ecologicalIndex);
   511→        setHistory(h => ({
   512→          ...h,
   513→          ecological: [...h.ecological.slice(-49), delta.ecologicalIndex!]
   514→        }));
   515→      }
   516→      if (delta.indigenousIndex !== undefined) {
