     1→/**
     2→ * Simulation Worker Client
     3→ *
     4→ * Main thread interface for communicating with simulation Web Worker.
     5→ * Provides a clean API for starting/stopping simulation and receiving updates.
     6→ *
     7→ * Usage:
     8→ *   const client = new SimulationWorkerClient();
     9→ *   client.on('update', (delta, month) => console.log('Month:', month));
    10→ *   client.init(42000, 'historical');
    11→ *   client.start();
    12→ */
    13→
    14→import type { ScenarioMode } from '@/types/game';
    15→
    16→// Re-export types from worker (expanded for comprehensive dashboard)
    17→export interface StateDelta {
    18→  // Core metrics
    19→  currentMonth?: number;
    20→  currentYear?: number;
    21→  qualityOfLife?: number;
    22→  population?: number;
    23→  aiCount?: number;
    24→  organizationCount?: number;
    25→
    26→  // AI System Metrics
    27→  dystopiaProgression?: number;
    28→  avgAICapability?: number;
    29→  deployedTechCount?: number;
    30→  alignedAICount?: number;
    31→  misalignedAICount?: number;
    32→  sleeperAgentCount?: number;
    33→  aiDeploymentPhase?: 'training' | 'testing' | 'deployed' | 'open_source';
    34→
    35→  // Environmental Metrics
    36→  climateChange?: number;
    37→  resourceDepletion?: number;
    38→  biodiversityLoss?: number;
    39→  pollutionLevel?: number;
    40→  planetaryBoundariesCrossed?: number;
    41→  environmentalDebtLevel?: number;
    42→
    43→  // Social Metrics
    44→  socialCohesion?: number;
    45→  institutionalTrust?: number;
    46→  meaningLevel?: number;
    47→  socialDebtLevel?: number;
    48→
    49→  // Crisis Indicators
    50→  activeCrises?: Array<{ type: string; severity: number; duration: number }>;
    51→  phosphorusDepletion?: number;
    52→  freshwaterStress?: number;
    53→  oceanAcidification?: number;
    54→  novelEntitiesLevel?: number;
    55→
    56→  // Government & Governance
    57→  governmentAIRegulation?: number;
    58→  governmentInvestment?: number;
    59→  governmentComprehension?: number;
    60→  internationalCooperation?: number;
    61→
    62→  // Technology & Research
    63→  activeResearch?: Array<{ tech: string; progress: number }>;
    64→  deployedTechs?: Array<{ name: string; tier: number; deployment: number }>;
    65→  techRiskLevel?: number;
    66→
    67→  // Upward Spirals & Outcomes
    68→  activeSpirals?: Array<{ type: string; strength: number; duration: number }>;
    69→  utopiaProgress?: number;
    70→  extinctionProbability?: number;
    71→  outcomeType?: string;
    72→
    73→  // Multi-Paradigm DUI (4 perspectives)
    74→  westernLiberalIndex?: number;
    75→  developmentIndex?: number;
    76→  ecologicalIndex?: number;
    77→  indigenousIndex?: number;
    78→
    79→  // Events (optional - only when significant changes happen)
    80→  events?: Array<{
    81→    type: string;
    82→    description: string;
    83→    severity?: 'low' | 'medium' | 'high' | 'critical';
    84→    category?: 'ai' | 'environment' | 'social' | 'crisis' | 'tech' | 'governance';
    85→  }>;
    86→
    87→  // Regional Populations (simplified view for dashboard)
    88→  regionalPopulations?: Array<{
    89→    name: string;
    90→    population: number; // millions
    91→    qualityOfLife: number; // [0, 1]
    92→    healthcareQuality: number; // [0, 1]
    93→    climateVulnerability: number; // [0, 1]
    94→  }>;
    95→
    96→  // AI Agents (individual agent data for detailed monitoring)
    97→  aiAgents?: Array<{
