function calculateDelta(previous: StateSnapshot, current: GameState, forceFull = false): StateDelta {
  const delta: StateDelta = {};

  // Capture current state snapshot for comparison
  const currentSnapshot = captureStateSnapshot(current);

  // On first step or when forced, send all metrics regardless of change
  if (isFirstStep || forceFull) {
    return { ...currentSnapshot } as StateDelta;
  }

  // Core metrics - always include month
  if (previous.currentMonth !== currentSnapshot.currentMonth) {
    delta.currentMonth = currentSnapshot.currentMonth;
  }

  workflowAdaptation: 0.21  // 21% baseline (2024 empirical data)
},

globalMetrics: {
  economicTransitionStage: 0,
  socialStability: 0.7,
  qualityOfLife: 0.65,
  wealthDistribution: 0.5,
  technologicalBreakthroughRate: 0.15,
  manufacturingCapability: 0.1,
  informationIntegrity: 0.6,
  publicTrust: 0.5, // Moderate baseline trust in technology (2025)
  population: 8.0 // Convenience accessor (synced with humanPopulationSystem.population)
},

// Initialize multi-dimensional QoL system
qualityOfLifeSystems: initializeQualityOfLifeSystems(),

// Phase 4-6: Multi-Paradigm DUI (initialized with neutral scores, updated by phase)
// Note: Baseline data loaded asynchronously, falls back to neutral if unavailable

